using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Restore the old property name so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonProperty("Discriminator");

        // Breaking change 2: id format changed from "Discriminator|Key" to just "Key" in EF Core 9.
        // Restore the old format so existing documents with "Blog|1" ids are still found.
        modelBuilder.Entity<Blog>().HasDiscriminatorInIdProperty();

        // Breaking change 3: HasIndex() now throws on the Cosmos provider instead of being silently ignored.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

